-- Questions difficiles du quiz d'exemple public (#210) : 7 nouvelles questions (une au moins par thème), les mêmes que dans
-- src/data/sample-quiz.json, ajoutées à la fin de la liste. Idempotent : une question dont l'identifiant existe déjà n'est
-- pas ajoutée une seconde fois. Ne touche que le quiz public de ce titre.
update public.quizzes q
set content = jsonb_set(q.content, '{questions}', q.content -> 'questions' || (
      select coalesce(jsonb_agg(n.question order by n.position), '[]'::jsonb)
      from jsonb_array_elements($j$[{"id":"hist-10","type":"text","theme":"histoire","difficulty":"hard","question":"Comment s'appellent les traités de 1648 qui ont mis fin à la guerre de Trente Ans ?","tags":["diplomatie"],"explanation":"Les traités de Westphalie, signés en 1648 à Münster et à Osnabrück, ont mis fin à la guerre de Trente Ans et réorganisé l'équilibre des puissances en Europe.","points":3,"content":{"expectedAnswers":["Traités de Westphalie","Traité de Westphalie","Paix de Westphalie","Westphalie"],"caseSensitive":false}},{"id":"sci-10","type":"qcm","theme":"sciences","difficulty":"hard","question":"Quel élément chimique a pour symbole « W » ?","tags":["chimie"],"explanation":"Le symbole W vient de « Wolfram », le nom allemand du tungstène.","points":3,"content":{"multiple":false,"answers":[{"id":"a","label":"Le tungstène","isCorrect":true},{"id":"b","label":"Le vanadium","isCorrect":false},{"id":"c","label":"Le zirconium","isCorrect":false}]}},{"id":"sci-11","type":"ordering","theme":"sciences","difficulty":"hard","question":"Classez ces planètes de la plus petite à la plus grande par leur diamètre.","tags":["astronomie"],"explanation":"Mercure (4 879 km), Mars (6 779 km), Vénus (12 104 km), puis la Terre (12 742 km) : Vénus est presque aussi grosse que la Terre.","points":3,"content":{"items":[{"id":"terre","label":"Terre"},{"id":"mercure","label":"Mercure"},{"id":"venus","label":"Vénus"},{"id":"mars","label":"Mars"}],"correctOrder":["mercure","mars","venus","terre"]}},{"id":"cine-10","type":"qcm","theme":"cinema","difficulty":"hard","question":"Quel film d'Alfred Hitchcock (1948) donne l'impression d'avoir été tourné en un seul plan-séquence ?","tags":["hitchcock"],"explanation":"La Corde, tourné en longs plans enchaînés dont les raccords sont dissimulés, donne l'impression d'un seul plan-séquence.","points":3,"content":{"multiple":false,"answers":[{"id":"a","label":"La Corde","isCorrect":true},{"id":"b","label":"Fenêtre sur cour","isCorrect":false},{"id":"c","label":"Sueurs froides","isCorrect":false}]}},{"id":"litt-10","type":"cloze","theme":"litterature","difficulty":"hard","question":"Le premier roman de la série des « Rougon-Macquart » d'Émile Zola s'intitule « La Fortune des ___ ».","tags":["romans-francais"],"explanation":"La Fortune des Rougon (1871) ouvre la série des vingt romans des Rougon-Macquart.","points":3,"content":{"expectedAnswers":["Rougon"],"caseSensitive":false}},{"id":"sport-10","type":"qcm","theme":"sport","difficulty":"hard","question":"Quel pays a accueilli et remporté la toute première Coupe du monde de football, en 1930 ?","tags":["football"],"explanation":"L'Uruguay a organisé la première Coupe du monde et l'a gagnée en battant l'Argentine en finale (4-2).","points":3,"content":{"multiple":false,"answers":[{"id":"a","label":"L'Uruguay","isCorrect":true},{"id":"b","label":"Le Brésil","isCorrect":false},{"id":"c","label":"L'Argentine","isCorrect":false}]}},{"id":"gastro-10","type":"text","theme":"gastronomie","difficulty":"hard","question":"Comment s'appelle la molécule responsable de la sensation de piquant du piment ?","tags":["science-culinaire"],"explanation":"La capsaïcine se fixe sur les récepteurs de la chaleur de la bouche : c'est elle qui donne la sensation de brûlure.","points":3,"content":{"expectedAnswers":["Capsaïcine","La capsaïcine"],"caseSensitive":false}}]$j$::jsonb) with ordinality as n (question, position)
      where not exists (select 1 from jsonb_array_elements(q.content -> 'questions') e where e ->> 'id' = n.question ->> 'id')
    )),
    updated_at = now()
where q.is_public and q.title = 'Culture générale';
